#include <bits/stdc++.h>
using namespace std;
string subtract_abs(string_view a,string_view b) { int n=max(a.size(),b.size()); if(a.size()<b.size() || (a.size()==b.size() && a<b))swap(a,b);string out(n,'0');int carry=0; for(int i=0;i<n;i++){int x=(i<(int)a.size()?a[a.size()-1-i]-'0':0), y=(i<(int)b.size()?b[b.size()-1-i]-'0':0); int v=x-y-carry;carry=v<0;if(carry)v+=10;out[n-1-i]=v+'0';}auto q=out.find_first_not_of('0');return q==string::npos?"0":out.substr(q);}
string palindrome(string h,int n){string p=h;for(int i=n/2-1;i>=0;i--)p+=h[i];return p;}
string gap(string s){int n=s.size(), k=(n+1)/2;string h=s.substr(0,k), best;auto offer=[&](const string& q){if(q.empty()||q[0]=='0')return;string d=subtract_abs(s,q);if(best.empty() || d.size()<best.size() || (d.size()==best.size() && d<best))best=move(d);}; offer(palindrome(h,n));for(int z:{-1,1}){string t=h;int c=(z==1?1:-1);for(int i=k-1;i>=0&&c;i--){int x=(t[i]-'0')+c;if(x==10){t[i]='0';c=1;}else if(x==-1){t[i]='9';c=-1;}else{t[i]='0'+x;c=0;}}if(!c && t[0]!='0')offer(palindrome(t,n));}if(n>1) offer(string(n-1,'9')); offer("1"+string(n-1,'0')+"1");return best;}
int main(int argc,char**argv){if(argc<5){cerr<<"seed  steps  stride  csv";return 1;}string seed=argv[1];int steps=atoi(argv[2]),stride=atoi(argv[3]);string path=argv[4];vector<uint8_t>a;for(auto i=seed.rbegin();i!=seed.rend();++i)a.push_back(*i-'0'); ofstream out(path);out<<"t,n,hamming,dist_exp,deficit,dist_mantissa,macro_drop\n";long long pal=0,gapdrops=0,hdrops=0,macro_bad=0;int max_def=-1,maxt=0,minh=INT_MAX;vector<string>window(stride+1);long long hprev=-1;for(int t=0;t<=steps;t++) {int n=a.size(),h=0;for(int j=0;j<n/2;j++)h+=(a[j]!=a[n-1-j]);if(h==0)pal++;if(hprev>=0&&h<hprev)hdrops++;hprev=h;minh=min(minh,h); string s; s.reserve(n);for(auto i=a.rbegin();i!=a.rend();++i)s.push_back(char('0'+*i));string d=gap(s);int exp=(int)d.size()-1,def=n/2-exp; if(def>max_def){max_def=def;maxt=t;}int bad=0;if(t>=stride){string old=window[t%(stride+1)];if(d.size()<old.size() || (d.size()==old.size() && d<=old)){bad=1;macro_bad++;}}window[t%(stride+1)]=move(d);if(true){const string &now=window[t%(stride+1)];out<<t<<","<<n<<","<<h<<","<<exp<<","<<def<<","<<now.substr(0,min(9,(int)now.size()))<<","<<bad<<"\n";}
 if(t==steps)break;int c=0;vector<uint8_t>b(n+1);for(int i=0;i<n;i++){int v=a[i]+a[n-1-i]+c;b[i]=v%10;c=v/10;}if(c)b[n]=c;else b.pop_back();a.swap(b);
 }
cerr<<"seed_len="<<seed.size()<<" steps="<<steps<<" stride="<<stride<<" pal="<<pal<<" hdrops="<<hdrops<<" macro_nonincrease="<<macro_bad<<" max_def="<<max_def<<" at="<<maxt<<" minimum_hamming="<<minh<<"\n";}